"""Freeze whole lowering poses against each facing's selected body and cargo."""
from pathlib import Path
import argparse,hashlib,json
ROOT=Path(__file__).resolve().parents[1];S=ROOT/'character/marsh-cargo-held-material-v1/sources'
ap=argparse.ArgumentParser();ap.add_argument('--facing',choices=['south','west'],required=True);args=ap.parse_args();f=args.facing
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
g=json.loads((S/'guide-provenance.json').read_text());r=g['facings'][f]
direction='SOUTH/toward-viewer' if f=='south' else 'WEST/LEFT side profile'
identity=('anatomicalRIGHT temple implant on viewerLEFT, swept blond hair, compact fitted adult head' if f=='south' else 'bare anatomicalLEFT visible temple, swept blond hair, implant on far anatomicalRIGHT temple hidden; never put an implant on the visible left temple')
case=('front-facing slate rectangular case with divided inset front panel and TWO small ivory latches, one at each upper corner' if f=='south' else 'side-profile slate rigid case with inset side panel and ONE visible ivory LEFT EDGE latch, pointing LEFT along body heading; never a frontal two-latch case')
poses=('Both figures face exactly SOUTH toward viewer, lean forward naturally with knees bending symmetrically and feet planted on both sides of case. Hands stay connected to either side/top of the case. Preserve adult thigh/shin/forearm lengths and compact head even in squat; hips and torso articulate, not shrink. Deep squat case rests on floor just in front of boots toward viewer, bottom at sole floor level.' if f=='south' else 'Both figures are fully WEST/LEFT side profile, head LEFT, knees/hips bent and spine leaning LEFT naturally. Both soles planted, short adult stable stance, no running or high-knee pose. Case stays in front toward LEFT, hands connected. Preserve adult thigh/shin/forearm lengths and compact head even in crouch. Deep squat case floor contact just LEFT ahead of boots, bottom at sole floor level.')
prompt=f'''Draw THREE separate complete adult Marsh {direction} game sprites in one horizontal row with wide transparent gutters: TWO complete crate-lowering figures and one unobstructed neutral standing ruler. ReferenceONE selected {f.upper()} idle is PRIMARY for body/head/limb proportions, elevated station camera, quiet warm matte pixel grade and fitted suit. ReferenceTWO exact staged {f.upper()} carry supplies rigid case dimensions and projection: {case}. ReferenceTHREE old unload board is MOTION ONLY; don't copy its older oversized head, enlarged shoulders or incorrect case projection. ReferenceFOUR original {f.upper()} master preserves {identity}, authentic boots and ankle hardware. Never mirror or turn to a different facing.
Figure1 HALF-LOWERING: whole adult in modest hip/knee crouch with SAME rigid case held halfway between waist and floor in front of knees, both connected arms supporting it. Figure2 FLOOR-LOWERING: whole adult deeper squat with SAME rigid case at floor contact, connected hands releasing it from top/sides. {poses} Case cannot grow, rotate into a different hardware face, hover, clip boots or pass through wrists. Preserve {case} at both stages, consistent physical dimensions. No enlarged portrait head, round child face, squashed torso, short limbs, exaggerated wide shoulders or shallow standing-repeat pose.
Figure3 exact unobstructed NEUTRAL {f.upper()} standing ruler matching PRIMARY, arms down, no crate. One147 occupied neutral calibration;184canvas,p92/172,H148. First/final runtime frames remain exact stagedcarry{f}0/selectedidle{f}0. Author only the two complete intermediates and one neutral, current four130ms nonloop520ms action. Pickup reverses whole frame order; never mirrored pixels. All three match own master material, grade, elevated camera and adult proportions. Transparent background, no floor graphic, shadow, glow, haze, text or labels.'''
p=S/f'{f}-unload-01.prompt.txt';assert not p.exists();p.write_text(prompt+'\n',encoding='utf-8')
refs=[S/f'{f}-body-primary.png',S/f'{f}-cargo-endpoint.png',S/f'{f}-held-motion-review.png',ROOT/f'character/marsh-motion-polish-v1/sources/{f}-standing-identity-01.png']
(S/f'{f}-unload-01.request.json').write_text(json.dumps({'normalAdmission':False,'fullGoalComplete':False,'status':'frozen before generation','promptSha256':sha(p),'orderedReferences':[{'path':q.relative_to(ROOT).as_posix(),'sha256':sha(q)} for q in refs],'sourceFrames':[r['primaryIdle'],r['stagedCargoEndpoint'],*r['selectedUnloadFrames']],'guideDependencies':[{'path':'tools/prepare_marsh_cargo_held_guides01.py','sha256':sha(ROOT/'tools/prepare_marsh_cargo_held_guides01.py')}],'sheetGrid':[3,1],'transparentBackground':True,'neutralOccupiedTargetHeight':147,'actionTimingMs':[130]*4,'wholeEndpointContract':[f'staged carry-{f}0',f'selected idle-{f}0'],'limits':'Review exact four refs before generation; no native action/admission/full-set acceptance.'},indent=2)+'\n');print(f+' two whole lowering poses plus neutral frozen')
